    // a series of predefined test cases
    createTestCase(
        'Multi reaction chains with ltoR direction reaction arrows, no merging',
        kcjChemDocMultiStepReactionsWithLtoRDirectionWithoutPlusSymbol1,
        null,
        [
            'm4 -> m5',
            'm1 . m2 -> m3 { m6 } -> m7 { m9 . m8 } -> m10',
            '-> m11'
        ],
        !true,
        {enableSiblingMerging: false}
    );
    createTestCase(
        'Multi reaction chains with ltoR direction reaction arrows, merged',
        kcjChemDocMultiStepReactionsWithLtoRDirectionWithoutPlusSymbol1,
        null,
        [
            'm4 -> m5',
            'm1 . m2 -> m3 { m6 } -> m7 { m9 . m8 } -> m10 -> m11'
        ],
        !true
    );

    createTestCase(
        'One reaction chains with multiple direction reaction arrows, no merging',
        kcjChemDocMultiStepReactionsWithMultipleDirections1,
        'C1CCCCC1 . c1ccccc1 . CrO3 { C1CCC1 . CC . CCC . C=C . C#C } -> C1CC1 . CCC . C=C',
        [
            'c1ccccc1 ->',
            'C1CCC1 ->',
            'C1CCCCC1 . c1ccccc1 . CrO3 { CC . CCC } -> C1CC1 . CCC . C=C -> C1CCC1 { C#CC } -> C1CCCCC1 { C#C . C=C } -> c1ccccc1'
        ],
        true,
        {enableSiblingMerging: false}
    );
    createTestCase(
        'One reaction chains with multiple direction reaction arrows, merged',
        kcjChemDocMultiStepReactionsWithMultipleDirections1,
        'C1CCCCC1 . c1ccccc1 . CrO3 { C1CCC1 . CC . CCC . C=C . C#C } -> C1CC1 . CCC . C=C',
        ['c1ccccc1 -> C1CCC1 -> C1CCCCC1 . c1ccccc1 . CrO3 { CC . CCC } -> C1CC1 . CCC . C=C -> C1CCC1 { C#CC } -> C1CCCCC1 { C#C . C=C } -> c1ccccc1'],
        true
    );

    createTestCase(
        'Multi reaction chains with shared starting reactant, no merging',
        kcjChemDocSharedReactantReactions1,
        'm1 { m5 } -> m2 . m3 . m4',
        [
            'm1 -> m6 -> m7',
            'm1 -> m2 . m3 -> m4',
            'm1 -> m5'
        ],
        false,
        {enableSiblingMerging: !true}
    );
    createTestCase(
        'Multi reaction chains with shared starting reactant, no merged',
        kcjChemDocSharedReactantReactions1,
        'm1 { m5 } -> m2 . m3 . m4',
        [
            'm1 -> m6 -> m7',
            'm1 -> m2 . m3 -> m4',
            'm1 -> m5'
        ],
        false
    );

    createTestCase(
        'Sorting with two reactions, TtoB / LtoR == default',
        kcjChemDocTwoReactionsForSorting,
        null,
        [
            'm1 -> m2',
            'm3 -> m4'
        ],
        false
    );
    createTestCase(
        'Sorting with two reactions, TtoB / LtoR == 10 / 1',
        kcjChemDocTwoReactionsForSorting,
        null,
        [
            'm3 -> m4',
            'm1 -> m2',
        ],
        false,
        {sortAxisWeightRatioXY: 1/10}
    );
    createTestCase(
        'Sorting with two reactions, TtoB / RtoL == 5 / 1',
        kcjChemDocTwoReactionsForSorting,
        null,
        [
            'm3 -> m4',
            'm1 -> m2',
        ],
        false,
        {sortAxisWeightRatioXY: 1/5, xSortMode: -1}
    );
    createTestCase(
        'Sorting with two reactions, BtoT / RtoL == 10 / 1',
        kcjChemDocTwoReactionsForSorting,
        null,
        [
            'm1 -> m2',
            'm3 -> m4',
        ],
        false,
        {sortAxisWeightRatioXY: 1/10, xSortMode: -1, ySortMode: 1}
    );

